  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const vw = innerWidth, out = { vw, vh: innerHeight, path: location.pathname };
  const header = document.querySelector('header');
  const hb = header ? header.getBoundingClientRect().bottom : 0;
  out.headerH = Math.round(hb);
  const vis = el => { const s = getComputedStyle(el); const r = el.getBoundingClientRect();
    return s.visibility !== 'hidden' && s.display !== 'none' && +s.opacity > 0.05 && r.width > 2 && r.height > 2; };
  const content = 'h1,h2,h3,h4,p,li,a,button,img,picture,video,iframe,input,select,textarea,label,summary,figure,svg[role=img]';
  // 1. gaps between consecutive top-level sections
  const secs = [...document.querySelectorAll('main > section, main > div > section, main > *, footer')].filter(vis);
  const uniq = [...new Set(secs)].sort((a,b)=>a.getBoundingClientRect().top-b.getBoundingClientRect().top);
  const box = el => { let top=Infinity, bot=-Infinity;
    el.querySelectorAll(content).forEach(c => { if (!vis(c) || c.closest('[aria-hidden=true]')) return; const r=c.getBoundingClientRect(); if (r.height>300 && c.tagName==='svg') return; top=Math.min(top,r.top+scrollY); bot=Math.max(bot,r.bottom+scrollY); });
    return {top, bot}; };
  out.gaps = [];
  for (let i=0;i<uniq.length-1;i++) { const a=box(uniq[i]), b=box(uniq[i+1]);
    if (isFinite(a.bot)&&isFinite(b.top)) out.gaps.push({from: (uniq[i].id||uniq[i].className||uniq[i].tagName).toString().slice(0,40), to:(uniq[i+1].id||uniq[i+1].className||uniq[i+1].tagName).toString().slice(0,40), gap: Math.round(b.top-a.bot)}); }
  // within-section vertical gaps between consecutive content blocks (largest 8)
  const blocks = [...document.querySelectorAll('main h2, main h3, main p, main ul, main img, main a, main button, main figure')].filter(vis)
    .map(e=>{const r=e.getBoundingClientRect();return {e, top:r.top+scrollY, bot:r.bottom+scrollY, t:(e.innerText||e.alt||e.tagName).trim().slice(0,30)}}).sort((a,b)=>a.top-b.top);
  const big=[]; let maxBot=-Infinity, last=null;
  for (const b of blocks) { if (last && b.top-maxBot>0) big.push({gap:Math.round(b.top-maxBot), after:last.t, before:b.t}); if (b.bot>maxBot){maxBot=b.bot; last=b;} }
  out.biggestGaps = big.sort((a,b)=>b.gap-a.gap).slice(0,10);
  // 2. hover rules not guarded by (hover:hover)
  let hoverUnguarded=0, hoverGuarded=0, samples=[];
  const walk=(rules,guard)=>{ for (const r of rules) { if (r.cssRules && r.media) walk(r.cssRules, guard || /hover\s*:\s*hover|pointer\s*:\s*fine/.test(r.media.mediaText)); else if (r.cssRules) walk(r.cssRules, guard);
      if (r.selectorText && r.selectorText.includes(':hover')) { if (guard) hoverGuarded++; else { hoverUnguarded++; if (samples.length<12) samples.push(r.selectorText.slice(0,80)); } } } };
  for (const s of document.styleSheets) { try { walk(s.cssRules,false); } catch(e){} }
  out.hover = {hoverUnguarded, hoverGuarded, samples};
  // 3. tight horizontal padding in pills/buttons
  out.tight = [];
  document.querySelectorAll('button, a, [role=tab], label').forEach(el=>{ if(!vis(el)) return; const r=el.getBoundingClientRect(); if (r.height<28||r.height>90) return;
    const rg=document.createRange(); rg.selectNodeContents(el); const tr=rg.getBoundingClientRect(); if (!tr.width) return;
    const bg=getComputedStyle(el); const pill = bg.backgroundColor!=='rgba(0, 0, 0, 0)' || bg.boxShadow!=='none' || bg.borderStyle!=='none';
    if (!pill) return; const l=tr.left-r.left, rt=r.right-tr.right;
    if (Math.min(l,rt) < 14 && r.width>40) out.tight.push({t:el.innerText.trim().slice(0,30), padL:Math.round(l), padR:Math.round(rt), w:Math.round(r.width)}); });
