  out.scrollers=[]; document.querySelectorAll('*').forEach(el=>{ const s=getComputedStyle(el); if(/(auto|scroll)/.test(s.overflowX) && el.scrollWidth>el.clientWidth+4 && vis(el)) {
    const kids=[...el.children].filter(vis); const clipped=kids.filter(k=>{const r=k.getBoundingClientRect(); return r.right>innerWidth+1||r.left<-1}).length;
    out.scrollers.push({cls:(el.className||el.tagName).toString().slice(0,40), items:kids.length, clippedOrOffscreen:clipped}); } });
