  const seen={}; document.querySelectorAll('main p, main li, main h2, main h3').forEach(el=>{ if(!vis(el))return; el.innerText.split(/(?<=[.?!])\s+/).forEach(s=>{s=s.trim(); if(s.length>25) (seen[s]=seen[s]||[]).push(1);});});
  out.dupes=Object.entries(seen).filter(([k,v])=>v.length>1).map(([k,v])=>({s:k.slice(0,90),n:v.length}));
  // 7. images: upscale + face-agnostic crop info
  out.images=[...document.images].filter(vis).map(i=>{const r=i.getBoundingClientRect(); return {src:(i.currentSrc||i.src).split('/').pop().split('?')[0].slice(0,40), shown:Math.round(r.width)+'x'+Math.round(r.height), nat:i.naturalWidth+'x'+i.naturalHeight, ratio:+(i.naturalWidth/(r.width*devicePixelRatio)).toFixed(2), pos:getComputedStyle(i).objectPosition}}).filter(x=>x.ratio<1);
