  out.anchors=[]; const ids=[...new Set([...document.querySelectorAll('a[href*="#"]')].map(a=>a.getAttribute('href').split('#')[1]).filter(Boolean))];
  for (const id of ids) { const t=document.getElementById(id); if(!t) {out.anchors.push({id, missing:true}); continue;}
    t.scrollIntoView({behavior:'instant', block:'start'}); await sleep(250);
    const h = t.querySelector('h2,h3,.eyebrow,[class*=eyebrow]') || t; const top=h.getBoundingClientRect().top;
    const headBot = header ? header.getBoundingClientRect().bottom : 0;
    out.anchors.push({id, firstText:(h.innerText||'').trim().slice(0,25), gapBelowHeader:Math.round(top-headBot)}); }
  scrollTo(0,0);
  return out;
})()

